// English for the web UI (设置 → 界面语言 → English; web/i18n.js). Keys are the
// Chinese as written: t`…` texts in web/*.js, with each ${…} as {0}, {1}…, and
// the shown texts of index.html. A value is the English, or a function of the
// parts where English needs it (plurals). npm test checks that nothing is missing
// (scripts/i18n-check.mjs).

/** "1 entry", "3 entries": counts may come formatted ("1,234"). */
const pl = (n, one, many) => `${n} ${Number(String(n).replace(/,/g, '')) === 1 ? one : many}`

