  "只管 Claude 模型（Anthropic 接口）。Opus 5.5、Fable 5.1 关不掉，选关闭也会思考。DeepSeek、GLM 和本地模型不看这里，要关思考，在供应商的「高级」里把「思考」选成关闭。": "For Claude models (Anthropic API) only. Opus 5.5 and Fable 5.1 always think, even when set to off. DeepSeek, GLM and local models ignore this: to turn their thinking off, set Thinking to Off under the provider's Advanced section.",
  "模型默认": "Model default",
  "DeepSeek、GLM、Qwen 和本地模型默认先思考。选关闭后这个供应商的模型都不思考，回复更快；个别服务不认时不起作用，模型还会照常思考。Claude 看「设置 → 模型」里的思考。对话顶栏给某个对话单独选的思考优先于这里。": "DeepSeek, GLM, Qwen and local models think first by default. Off stops it for all of this provider's models, for faster replies; a service that does not take it goes on thinking. Claude follows Thinking under Settings → Models. Thinking picked for one chat in its top bar wins over this.",
