  "随时生效。顶栏可以给每个对话单独选模型和思考，单独选的思考优先于这里和供应商的设置。": "Takes effect immediately. In the top bar you can pick a model and thinking for each chat; thinking picked there wins over this and over the provider's setting.",
  "思考：默认（{0}）": "Thinking: default ({0})",
  "思考：关（这个模型关不掉）": "Thinking: off (this model can't turn it off)",
