  "这个对话的回复思考多少。默认跟随设置和供应商；选了别的只管这个对话，下一轮起生效": "How much this chat's replies think. Default follows the settings and the provider; anything else applies to this chat only, from the next reply",
  "卡没指定就用默认的。只影响这张卡之后新开的对话；当前对话要不要跟着换，保存时会问你。导出角色卡时不会带上。": "A card that picks none uses the default. This only affects chats started on this card from now on; when you save, you're asked whether the open chat switches too. Exported cards don't carry these.",
  "写作语言": "Writing language",
