  "例如：第三人称限知视角，白描为主，少用形容词堆砌；对白口语化。": "e.g. Third-person limited point of view, mostly plain description without piles of adjectives; conversational dialogue.",
  "世界书扫描最近几条": "Lorebook scans the last N messages",
