  "不清（压缩上下文时才重置）": "Never (reset only when you compact the context)",
  "动态设定（变量列表）在历史里堆多了会一次性删掉；删的那一轮要重写整段历史的缓存。删得少更省，但上下文长得快些。": "Dynamic lore (the variable list) piles up in the history and gets cleared all at once; the turn that clears it has to rewrite the cache for the whole history. Clearing less often is cheaper, but the context grows faster.",
  "挂上的世界书和卡里自带的一起生效：常驻条目进固定前缀，关键词条目按最近的对话触发。": "Attached lorebooks work together with the card's own: constant entries go into the fixed prefix, and keyword entries trigger on recent messages.",
  "访问海外接口": "Proxy for overseas APIs",
  "不用代理": "No proxy",
  "显示模型的思考过程": "Show the model's thinking",
  "打开后，模型的思考过程折叠显示在回复上方，生成时可以展开看。GLM、DeepSeek、Kimi、OpenRouter、Claude（Anthropic 接口）本来就会发回来；Gemini 和 OpenAI（Responses 接口）只在要的时候给一份思考摘要，打开后会向它们要（有的中转不给）。只是显示，不会发回给模型，也不算进正文。模型没发思考过程时什么也不显示；努力程度是 low 时，有的模型（比如 GLM）遇到简单的回合会不思考。": "With this on, the model's thinking shows folded above each reply, and you can open it while the reply is written. GLM, DeepSeek, Kimi, OpenRouter and Claude (Anthropic API) send it back anyway; Gemini and OpenAI (Responses API) give a summary of it only when asked, so with this on they are asked (some relays leave it out). It is only shown: it is never sent back to the model and is not part of the story. Nothing shows when a model sends no thinking; at effort low, some models (GLM, say) skip thinking on an easy turn.",
  "指定代理地址": "Custom proxy address",
  "代理地址": "Proxy address",
  "「跟随系统代理」读 Windows 或 macOS 的代理设置（Clash、v2rayN、ClashX 开了「系统代理」时就是它），每分钟更新一次。只支持 HTTP 代理，SOCKS 不行。供应商设成「直连」的（DeepSeek 等国内服务）不走代理。保存后立刻生效。": "\"Use system proxy\" reads the Windows or macOS proxy settings (what Clash, v2rayN or ClashX set when their \"System proxy\" is on) and refreshes them every minute. Only HTTP proxies work, not SOCKS. Providers set to \"Direct\" (DeepSeek and other services in mainland China) skip the proxy. Takes effect as soon as you save.",
  "谁可以打开": "Who can open it",
  "同一 WiFi 或 Tailscale": "Same Wi-Fi or Tailscale",
  "改完要重启服务。不要把端口映射到公网：拿到链接的人能用你的模型额度。出门时在电脑和手机都装 Tailscale，用这里的 Tailscale 地址打开。手机打不开时，在 Windows 防火墙里允许 Node.js 入站；Mac 上在 系统设置 › 网络 › 防火墙 里允许 CicaTavern 传入连接。": "Restart the server after changing this. Don't expose the port to the internet: anyone with the link can use your model quota. When you're away from home, install Tailscale on both the computer and the phone and open the Tailscale address shown here. If the phone can't connect, allow inbound connections for Node.js in Windows Firewall; on a Mac, allow incoming connections for CicaTavern in System Settings › Network › Firewall.",
