  "套一个模板：属性、生命、敌人档位这些的叫法，气力的叫法和开局技能。规则本身不变。叫法马上生效，开局技能只影响新故事。": "Puts on a template: what attributes, life, foe tiers and energy are called, and the starting skills. The rules underneath stay the same. Names take effect at once; starting skills only in new stories.",
  "让辅助模型读这张卡，给出题材、叫法、属性、技能、物品、常见敌人、同伴、等级阶梯和变量绑定，你看过再采用。": "The helper model reads this card and proposes a genre, names, attributes, skills, items, common foes, companions, ranks and variable links. Nothing changes until you take it.",
  "这张卡怎么叫这些东西，界面和发给模型的规则一起换。只换名字，数值和存档不变；空着就用默认的叫法。": "What this card calls these things, on screen and in the rules sent to the model. Only the names change, not the numbers or saves; empty uses the default name.",
