  "绑定变量": "Linked variables",
  "这张卡已有的变量可以当作生命、背包这些来用：故事里归卡管，用物品时由规则写回。": "Variables this card already has can serve as life, items and so on: the card keeps them in the story, and the rules write them back when you use something.",
  "打开这张卡的对话后才能选变量。": "Open a chat with this card to pick variables.",
