  "续写": "Continuing",
  "已清掉历史里堆积的变量列表（{0} 字）。这一轮会重写对话历史的缓存，固定前缀还在。": n => `Cleared the variable lists piled up in the history (${pl(n, 'character', 'characters')}). This turn rewrites the chat history's cache; the fixed prefix stays cached.`,
  "「{0}」这一轮写好了": "\"{0}\": the new turn is ready",
