  "按现在的角色卡、设置和预设重新生成这个对话的固定前缀？历史不变；下一轮会重新写入一次缓存（大卡约占一轮的额度）。": "Rebuild this chat's fixed prefix from the current card, settings and preset? The history stays as it is; the next turn writes the cache once more (about one turn's worth of quota for a big card).",
