  "ComfyUI 地址": "ComfyUI URL",
  "导入工作流": "Import workflow",
  "在 ComfyUI 里「导出（API）」再导入就行：酒馆顺着采样器找到正向和负面提示词、宽高，种子每次自动随机。要指定写在哪，把正向提示词写成 %prompt%（不要写 {{prompt}}，导出时花括号会被 ComfyUI 去掉）、负面写 %negative_prompt%；要用参考图，LoadImage 写 \"%char_avatar%\"（会上传这张卡的头像）。SillyTavern 的 ComfyUI 工作流可以直接导入。": "Just use \"Export (API)\" in ComfyUI and import it here: the tavern follows the samplers to the positive and negative prompts and the size, and picks a new seed each time. To choose where they go, write the positive prompt as %prompt% (not {{prompt}}: ComfyUI drops the braces when exporting) and the negative as %negative_prompt%; for a reference picture, set LoadImage to \"%char_avatar%\" (this card's avatar is uploaded). SillyTavern's ComfyUI workflows import as they are.",
  "留空不改": "Leave blank to keep",
  "检查": "Check",
  "正在查 V5 额度…": "Checking the V5 quota…",
  "查不到额度：{0}": "Couldn't check the quota: {0}",
  "删除令牌": "Delete token",
  "已删除 NovelAI 令牌": "NovelAI token deleted",
  "NovelAI 持久令牌": "NovelAI persistent token",
  "在 NovelAI 网页点左下角齿轮 →「Account」→「Get Persistent API Token」，复制后粘贴到这里再保存。「检查」只查订阅、V5 额度和 Anlas，不画图。": "On the NovelAI website, click the gear at the bottom left → \"Account\" → \"Get Persistent API Token\", copy it, paste it here and save. \"Check\" only looks up your subscription, V5 quota and Anlas; it doesn't draw anything.",
  "V5 额度用完时": "When the V5 quota runs out",
  "改用 V4.5 画（Opus 不扣 Anlas）": "Draw with V4.5 instead (no Anlas on Opus)",
  "继续用 V5，扣 Anlas": "Keep using V5 and spend Anlas",
  "Opus 的 V5 有一份额度，每小时回一点，用完后 NovelAI 改扣 Anlas。每次画 V5 前先查一下：剩 10% 以下时图下面会提醒，用完时按这里处理。": "Opus comes with a V5 quota that refills a little every hour; once it's used up, NovelAI charges Anlas instead. It's checked before each V5 picture: below 10% you get a note under the picture, and when it's empty this setting decides.",
  "画面里只有一个名册角色（或者除了主角只有一个）、而且她有人设图时，照人设图画（自动改用 V4.5，每张多扣 5 Anlas，不够时这张不带；V5 还不支持人设图）": "When the scene has only one roster character (or only one besides the protagonist) and they have a reference image, draw from it (switches to V4.5 automatically and costs 5 extra Anlas per picture, skipped for that picture if you're short; V5 doesn't support reference images yet)",
  "人设图还原度": "Reference fidelity",
  "越高越像人设图，越低越听提示词": "Higher looks more like the reference image, lower follows the prompt more",
  "连画风一起参考": "Copy its art style too",
  "质量词（加在每张提示词后面）": "Quality tags (added after every prompt)",
  "负面提示词": "Negative prompt",
  "尺寸和步数都在 Opus 的免费范围内（不超过 1024×1024 像素、23 步）：V4.5 不限量，V5 用上面那份额度，都不扣 Anlas。走「设置」里的代理。": "Size and steps stay within Opus's free range (up to 1024×1024 pixels, 23 steps): V4.5 is unlimited and V5 uses the quota above, so neither spends Anlas. Uses the proxy in \"Settings\".",
  "用这张卡的头像当参考图（走 /images/edits，长相更稳定）": "Use this card's avatar as a reference image (via /images/edits, for a steadier look)",
  "参考图用的模型": "Model for reference images",
  "有的网关生图和改图是两个模型：grok2api 只有 Web 账号时，2.0 只能生图，改图要用 grok-imagine-image-edit。改图失败时这张会自动不带参考图再画。": "Some gateways use one model to generate and another to edit: with grok2api on Web accounts only, 2.0 can only generate and editing needs grok-imagine-image-edit. If editing fails, the picture is drawn again without the reference image.",
  "不用就留空": "Leave blank if unused",
  "已连上{0}，{1} 个音色": (via, n) => `Connected${via}, ${pl(n, 'voice', 'voices')}`,
  "（经电脑上的酒馆）": " (via CicaTavern on your computer)",
  "（在线）": " (online)",
  "云端服务 · {0} · {1}（按字数计费）": "Cloud service · {0} · {1} (billed per character)",
  "{0} · 本地模型音色": "{0} · local model voices",
  "{0} · 经它转发的云端音色（按字数计费）": "{0} · cloud voices it relays (billed per character)",
  "{0}（{1} · {2}）": "{0} ({1} · {2})",
  "浏览器 · 这台设备自带的音色（免费）": "Browser · this device's built-in voices (free)",
  "{0}（这台设备没有，用默认中文音色）": "{0} (not on this device; uses the default Chinese voice)",
  "{0}（现在没有）": "{0} (not available now)",
  "试听": "Preview",
  "用这个音色读一句示例（没保存的设置也算）": "Read a sample line in this voice (unsaved settings count too)",
  "{0}当前的音色{1}": "{0}'s current voice{1}",
  "浏览器默认中文音色": "Browser's default Chinese voice",
  "经语音桥接转发的云端音色，用桥接自己「云端 API 设置」里的密钥和模型。云端音色都按字数计费，旁白字多，用本地模型或浏览器音色更省": "Cloud voices relayed by the voice bridge use the key and model in the bridge's own \"Cloud API settings\". All cloud voices are billed per character, and narration is long, so a local model or browser voice costs less",
  "云端音色按字数计费；旁白字多，用本地模型或浏览器音色更省": "Cloud voices are billed per character; narration is long, so a local model or browser voice costs less",
  "浏览器音色是这台设备自带的，免费；换一台设备可能没有同一个，会改用它的默认中文音色。": "Browser voices come with this device and are free; another device may not have the same one and will use its default Chinese voice instead.",
  "回复里 [voice:情绪:台词] 的情绪：Fish 放在台词前当语气标签，gpt-4o-mini-tts 当语气说明，其余音色不读": "The emotion in [voice:emotion:line] tags in replies: Fish puts it before the line as a tone tag, gpt-4o-mini-tts takes it as a tone instruction, other voices ignore it",
  "本机填语音桥接的地址（比如 http://127.0.0.1:8765），用它跑的本地 TTS 模型，或它转发的云端音色。手机上没有语音桥接：把电脑上酒馆「设置 → 手机访问」里的链接整条粘贴进来，同一个 Wi-Fi 下借电脑朗读（电脑上的云端密钥留在电脑上）。": "On this computer, enter the voice bridge's address (http://127.0.0.1:8765, say) to use the local TTS models it runs or the cloud voices it relays. No voice bridge on your phone? Paste the whole link from \"Settings → Phone access\" in CicaTavern on your computer, and the computer reads aloud for you on the same Wi-Fi (its cloud keys stay on the computer).",
  "本机或局域网里跑 TTS 模型的服务（兼容 POST /api/tts 和 GET /api/persona/list）。也可以把另一台电脑上酒馆「设置 → 手机访问」里的链接整条粘贴进来，借那台电脑设好的音色（密钥留在那台电脑上）。": "A service on this computer or your local network that runs TTS models (supports POST /api/tts and GET /api/persona/list). You can also paste the whole link from \"Settings → Phone access\" in CicaTavern on another computer to use the voices set up there (the keys stay on that computer).",
  "{0}（本机 / 电脑上的酒馆）": "{0} (this computer / CicaTavern on a computer)",
