  "画面提示词怎么写": "How the image prompt is written",
  "「接着对话写」把固定前缀和这段对话原样发给写这段剧情的模型，再追加一句要提示词：几乎全部命中缓存，人物现在穿什么、在哪都对得上，但用的是对话模型的价格和速度。": "\"Continue the chat\" sends the fixed prefix and this chat as they are to the model that wrote this part of the story, plus one request for a prompt: nearly all of it hits the cache, and what the characters are wearing and where they are stays right, but you pay the chat model's price and wait at its speed.",
  "订阅模型写的剧情借不了，会自动改用辅助模型。": "Parts written by a subscription model can't be borrowed this way; the helper model takes over automatically.",
  "辅助模型": "Helper model",
  "还没有供应商的模型": "No provider models yet",
  "提示词写法": "Prompt style",
  "不留旧图": "Keep none",
  "留 {0} 张旧图": n => `Keep ${n}`,
  "重画后留几张旧图": "Earlier pictures to keep",
  "配图、人设图、立绘和表情、场景、头像重画或换图后，每处留最近这么多张旧图，点一张就能换回来；再多的从最旧的删。调小了，每处下次重画时删到这个数。旧图不随对话包和角色卡导出。": "When a picture, reference image, sprite or expression, scene or avatar is redrawn or replaced, each keeps this many of its latest earlier pictures, to bring one back with a click; past that, the oldest go. Lowered, each place drops to it the next time it's redrawn. Earlier pictures don't go into chat packages or card exports.",
  "画风与 LoRA": "Art style & LoRA",
  "画风：{0}": "Art style: {0}",
  "还没写画风": "No art style yet",
  "LoRA：{0}": "LoRA: {0}",
  "画风（写进画面提示词；人设图、立绘也加，NovelAI、ComfyUI、SD WebUI 每张都加）": "Art style (goes into image prompts, reference pictures and sprites too; NovelAI, ComfyUI and SD WebUI add it to every picture)",
  "例如 anime style, delicate lineart, soft cel shading, soft lighting": "e.g. anime style, delicate lineart, soft cel shading, soft lighting",
  "画风负面（加在负面提示词后面：NovelAI、ComfyUI、SD WebUI）": "Art style negative (added after the negative prompt: NovelAI, ComfyUI, SD WebUI)",
  "例如 lowres, bad anatomy, bad hands, worst quality, watermark": "e.g. lowres, bad anatomy, bad hands, worst quality, watermark",
  "两种方式都用。导入的工作流里自己写的负面提示词照样保留，这里的加在后面；写了 %negative_prompt% 的就填在那里。CFG 是 1 时负面提示词不起作用。": "Used either way. An imported workflow keeps the negative prompt written in it, with this added after; one with %negative_prompt% gets it there. At CFG 1 the negative prompt has no effect.",
  "例如 realistic, 3d, chibi": "e.g. realistic, 3d, chibi",
  "整卡 LoRA（ComfyUI 和 SD WebUI 用；人设图、立绘也用，名册里自带 LoRA 的角色单独出镜时改用她自己的）": "Card LoRA (ComfyUI and SD WebUI; reference pictures and sprites use it too; a cast member with a LoRA of their own uses theirs when drawn alone)",
  "不用": "None",
