  "画这张卡时自动在工作流的 Load Checkpoint 后面接上它，并把触发词放在提示词最前面。": "When drawing this card, it's hooked in after the workflow's Load Checkpoint automatically, and the trigger word goes at the very start of the prompt.",
  "ComfyUI 没开，列不出 LoRA 文件；开着 ComfyUI 再打开这里。": "ComfyUI isn't running, so LoRA files can't be listed; start ComfyUI and open this again.",
