  "配图和朗读都是点了才做，不进模型的上下文，也不影响缓存。": "Pictures and reading aloud happen only when you click; they never enter the model's context and don't affect the cache.",
  "管理供应商": "Manage providers",
  "女": "Female",
  "男": "Male",
  "名册里的人，长相按这里写的固定 tag 画，辅助模型只写谁在画面里、穿什么、在做什么。多人同框时每人单独成段，不会串。外貌和衣着用英文 tag。点一个人展开编辑。": "Characters in the roster are drawn from the fixed tags written here; the helper model only writes who is in the scene, what they wear and what they're doing. With several characters in one picture, each gets their own section, so they don't blend. Write looks and outfits as English tags. Tap someone to edit them.",
