  "账户里的 {0} 个音色都已在列表里{1}": (n, rest) => `${Number(String(n).replace(/,/g, '')) === 1 ? 'The voice in your account is' : `All ${n} voices in your account are`} already in the list${rest}`,
  "，补上了名字，保存后生效": "; names filled in, takes effect when you save",
