  "供应商的朗读接口（OpenAI 兼容 /audio/speech）": "Provider speech API (OpenAI-compatible /audio/speech)",
  "音色（每行一个：ID，后面可以空一格写名字）": "Voices (one per line: ID, optionally followed by a space and a name)",
  "coral 温柔\nnova": "coral Gentle\nnova",
  "留空就用模型常见的音色：OpenAI 的 alloy、coral、nova…；硅基流动 FunAudioLLM/CosyVoice2-0.5B 的 8 个预置音色。用供应商自己的地址、密钥和代理设置；gpt-4o-mini-tts 会把回复里的情绪当语气说明。": "Leave blank for the model's usual voices: OpenAI's alloy, coral, nova…; the 8 preset voices of SiliconFlow's FunAudioLLM/CosyVoice2-0.5B. Uses the provider's own URL, key and proxy settings; gpt-4o-mini-tts takes the emotions in replies as tone instructions.",
  "fish.audio → API Keys 里创建": "Create one at fish.audio → API Keys",
  "音色（每行一个：音色页链接或 32 位 ID，后面可以空一格写名字）": "Voices (one per line: voice page link or 32-character ID, optionally followed by a space and a name)",
  "https://fish.audio/m/0123456789abcdef0123456789abcdef 南晚": "https://fish.audio/m/0123456789abcdef0123456789abcdef Nanwan",
  "自己克隆的音色点「从账户读取音色」；别人的音色在 fish.audio 打开，复制地址栏的链接粘贴进来。回复里的情绪放在台词前当语气标签。除 s2.1-pro-free 外按字数计费，账户没余额时换成它；走「设置」里的代理。": "For voices you cloned, click \"Load voices from account\"; for other people's voices, open them on fish.audio and paste the link from the address bar. Emotions in replies go before the line as tone tags. Billed per character except s2.1-pro-free, so switch to it when your account has no balance. Uses the proxy in \"Settings\".",
  "开放平台 → 接口密钥": "Open Platform → API Keys",
  "站点": "Site",
  "国内站（api.minimaxi.com，直连）": "China site (api.minimaxi.com, direct)",
  "国际站（api.minimax.io，走代理）": "International site (api.minimax.io, via proxy)",
  "密钥只在创建它的站点能用": "A key only works on the site where it was created",
  "音色（每行一个：voice_id，后面可以空一格写名字）": "Voices (one per line: voice_id, optionally followed by a space and a name)",
  "留空用系统音色（少女、御姐、精英青年…）": "Leave blank for system voices (young girl, mature lady, elite young man…)",
  "复刻或设计的音色点「从账户读取音色」，或者把 voice_id 写在这里。按字数计费。": "For cloned or designed voices, click \"Load voices from account\", or write the voice_id here. Billed per character.",
