  "已导入：{0} 个节点，占位符 {1}": (n, placeholders) => `Imported: ${pl(n, 'node', 'nodes')}, placeholders ${placeholders}`,
  "找不到酒馆能改的宽高，选的画幅不会生效：把 Empty Latent Image 的宽高改成 %width% 和 %height%，再导出（API）导入": "No width and height the tavern can change, so the picture size you pick won't take effect: set Empty Latent Image's width and height to %width% and %height%, then export (API) and import again",
  "{0} 也定了尺寸，酒馆不改它，画出来可能不是选的画幅": "{0} also sets a size, which the tavern leaves alone, so pictures may not come out at the size you pick",
  "CFG 是 1（加速版模型常这样），负面提示词不起作用：立绘的「不要背景」只靠正面提示词，抠不干净时可以多画几张": "CFG is 1 (as with most turbo models), so the negative prompt has no effect: sprites ask for no background in the prompt alone, so draw a few more if one doesn't cut out cleanly",
  "负面提示词加不进去，立绘的「不要背景」用不上：把负面提示词改成 %negative_prompt%，再导出（API）导入": "The negative prompt can't be added to, so sprites can't ask for no background: set the negative prompt to %negative_prompt%, then export (API) and import again",
