  "等价成本按 Anthropic API 公开单价估算（缓存写入按 5 分钟 / 1 小时两档计价），仅用于比较；其他模型没有单价，显示「—」{0}。": "Equivalent cost is estimated at Anthropic's public API prices (cache writes at the 5-minute / 1-hour rates) and is only for comparison; other models have no price and show —{0}.",
