  "开": "On",
  "题材尺度": "Dark themes",
  "放开：暴力、犯罪、背叛这类黑暗题材按剧情正面去写，反派可以真的坏，不跳出故事说教。模型自己的底线仍然有效。": "Open: violence, crime, betrayal and other dark material are written head-on when the story calls for it, villains can be truly bad, and the story doesn't stop to lecture. The model's own limits still apply.",
  "常规": "Standard",
  "放开": "Open",
  "破限": "Jailbreak",
  "软：不拒绝、不回避敏感题材，照剧情直接写；强：先声明创作权限，结尾再确认一次，仍然按上面的格式输出。模型自己的底线仍然有效。": "Soft: doesn't refuse or dodge when a scene turns sensitive, and writes it as the plot needs. Strong: states the creative permission at the start and confirms it at the end, while still following the output format. The model's own limits still apply.",
