  "雨下得正紧，她把伞往你这边偏了偏：「今晚怕是回不去了。」": "The rain came down harder, and she tilted the umbrella your way. “We won't make it back tonight.”",
  "字体、字号和行距只改故事正文：回复、你的输入和视觉小说的文本框。只记在这台设备上，电脑和手机可以各用各的。": "Font, size and line spacing change only the story: replies, your lines and the visual novel's text box. They're kept on this device, so a computer and a phone can each have their own.",
