  // 正则集 and the regex window laid out as the lorebook one (web/regex.js, card-edit.js)
  "依次运行：全局 → 预设 → 卡里自带 → 挂到这张卡的正则集（按列表顺序）。只改显示的正则不影响缓存；会改发给模型内容的，改完下一轮会重新写入一次缓存。": "They run in order: global → preset → the card's own → the regex sets on that card (in list order). Display-only regex never touches the cache; one that changes what is sent makes the next turn write the cache once more.",
  "导入 SillyTavern 导出的正则（.json），放进选中的这一组（选中的不能改时放进全局）": "Import regex exported from SillyTavern (.json) into the selected group (into the global ones when that one can't change)",
  "新建一个正则集：挂到哪些角色卡上，就只对那几张卡生效": "Create a regex set: it works only on the cards you put it on",
  "全局 {0} 条": n => pl(n, 'global script', 'global scripts'),
  "导入或新建全局正则": "Import or create global regex",
  "正则集 {0} 个": n => pl(n, 'regex set', 'regex sets'),
  "可以建正则集挂到指定的卡上": "regex sets can go on chosen cards",
  "卡和预设自带的也在这里开关": "the ones in cards and presets switch here too",
