  "{0} 没在最近几轮里找到名册之外的角色，也没有要补的名字。": "{0} found nobody in the latest turns who isn't in the cast list, and no names to add.",
  "从对话里补充": "Add from the chat",
  "读正在打开的对话最近几轮：列出后来出场、名册里还没有的角色，给已有的角色补上剧情里的外号、改正写错的名字": "Reads the latest turns of the open chat: lists characters who joined later and aren't in the cast list, adds the nicknames the story uses for those who are, and fixes names written wrong",
