  "不要了": "Discard",
  "按这张卡的角色画一张方形头像：脸和肩膀，用这张卡的画风。长相取角色名册里的；名册里没有，就让辅助模型从卡里读，再不行就照描述画。": "Draws a square avatar of this card's character: face and shoulders, in the card's style. The looks come from the character roster; if it has none, the helper model reads them from the card, and failing that the description is used.",
  "Gemini 原生生图": "Gemini native image generation",
  "还没选供应商": "No provider chosen yet",
