  "设置里用的{0}{1}：换一种画法，或者先去设置。": (method, need) => `The ${method} in Settings: ${need.charAt(0).toLowerCase()}${need.slice(1)}. Pick another backend, or set it up first.`,
  "用导入的 ComfyUI 工作流画，模型在工作流里。": "Draws with the imported ComfyUI workflow; the model is set in the workflow.",
