  "按方案里的长相和上面的画面描述画。": "Draws from the looks in the plan and the scene description above.",
  "同一段提示词再画一张换掉这张，可以先选画图方式和模型；这张留在旧图里": "Draw another with the same prompt in this one's place; you can pick the image backend and model first. This one is kept with the earlier ones",
  "重画这张图": "Redraw this picture",
  "同一段提示词再画一张，换掉这张；这张留在旧图里，随时换回来。": "Draws another with the same prompt in this one's place. This one is kept with the earlier ones, to bring back any time.",
  "同一段提示词再画一张，换掉这张（设置里旧图留 0 张，这张不留）。": "Draws another with the same prompt in this one's place (the settings keep no earlier pictures, so this one isn't kept).",
  "这张图用什么画": "What to draw this picture with",
  "按长相和平时衣着画一张半身像当人设图，可以先选画图方式和模型（NovelAI 在 Opus 免费范围内）": "Draw a half-body portrait from the looks and usual outfit to use as the reference image; you can pick the image backend and model first (NovelAI stays within Opus's free range)",
  "画「{0}」的人设图": "Draw a reference image of \"{0}\"",
