  // 世界书 / 预设 → 对话修改 (talk.js, talk-dialog.js, books.js, presets.js)
  "采用了 {0} 处，后来撤销了": n => `Applied ${pl(n, 'change', 'changes')}, then undone`,
  "撤销这次修改": "Undo this change",
  "改回采用之前的样子": "Go back to how it was before these changes went in",
  "撤销这次修改，改回采用之前的样子？": "Undo this change and go back to how it was before it went in?",
  "可以一条条新增，也可以说说这本书写什么，让向导写出来。": "Add entries one by one, or say what the lorebook should hold and let the guide write it.",
  "用对话来写": "Write it by chat",
  "在「对话修改」里说说这一条想怎么改": "Say in \"Edit by chat\" how this entry should change",
  "在「对话修改」里说说这一条想怎么改，或者问它在做什么": "Say in \"Edit by chat\" how this entry should change, or ask what it does",
  "说说想怎么改，向导把要改的条目整条写出来，勾上的才会改进书里": "Say what you'd like changed: the guide writes out each entry it would change, and only the ones you tick go into the lorebook",
  "说说想怎么改，或者问问某一条在做什么：向导把要改的条目整条写出来，勾上的才会改进预设": "Say what you'd like changed, or ask what an entry does: the guide writes out each entry it would change, and only the ones you tick go into the preset",
  "对话修改世界书": "Edit lorebook by chat",
  "对话修改预设": "Edit preset by chat",
  "「{0}」卡里自带": "Built into \"{0}\"",
  "说说这本世界书写什么：世界的规则、人物、地点、组织……向导一条条写出来，勾上的才会写进书里，写完还能接着说怎么改。": "Say what this lorebook should hold: the world's rules, characters, places, groups… The guide writes them entry by entry; only the ones you tick go into the lorebook, and you can keep talking to change them.",
  "说说想怎么改这本世界书：向导把要改的条目整条写出来，改前改后对照着给你看，勾上的才会改进书里。也可以只是问问，比如哪些设定互相矛盾。": "Say how this lorebook should change: the guide writes out each entry it would change and shows it before and after; only the ones you tick go into the lorebook. You can also just ask, such as which settings contradict each other.",
  "修仙世界：三个宗门、两座城，灵气正在枯竭": "A cultivation world: three sects, two cities, and the spiritual energy running dry",
  "现代都市：深夜才营业的花店和它的常客": "A modern city: a flower shop open only late at night, and its regulars",
  "给人物条目补全关键词": "Fill in keywords for the character entries",
  "查查有没有互相矛盾的设定": "Check for settings that contradict each other",
  "太长的条目拆成几条": "Split entries that are too long",
  "「{0}」想怎么改，比如：写短一点，加上她的口头禅": "How should \"{0}\" change? E.g. shorter, with her catchphrase",
  "说说这本书写什么，比如：一座雨夜才开门的旧城": "Say what the lorebook is about, e.g. an old town that opens only on rainy nights",
  "说说想怎么改，比如：给每个人物补上外号当关键词": "Say what you'd like changed, e.g. add each character's nicknames as keywords",
  "书比较长，先看目录挑要读的条目…": "The lorebook is long: looking through its contents for the entries to read…",
  "正在写，已经写了 {0} 字…": n => `Writing, ${pl(n, 'character', 'characters')} so far…`,
  "正在读这本世界书…": "Reading the lorebook…",
  "书名和简介": "Name and description",
