  "删除条目 · {0}": "Delete entry · {0}",
  "条目 · {0}": "Entry · {0}",
  "不再发给模型": "No longer sent to the model",
  "书名：{0} → {1}": "Name: {0} → {1}",
  "改成常驻：写进对话开局时的固定前缀": "Made constant: written into the fixed prefix when a chat starts",
  "改成关键词触发": "Made keyword-triggered",
  "已改进书里：{0} 处": n => `${pl(n, 'change', 'changes')} applied to the lorebook`,
  "已撤销这次修改": "This change was undone",
  "说说想怎么改这个预设，或者问问某一条在做什么：向导把要改的条目整条写出来，改前改后对照着给你看，勾上的才会改进预设。": "Say how this preset should change, or ask what an entry does: the guide writes out each entry it would change and shows it before and after; only the ones you tick go into the preset.",
  "这个预设大概在做什么？": "What does this preset do, roughly?",
  "文风改得口语一些": "Make the style more conversational",
  "加一条：每轮回复不超过 600 字": "Add one: keep each reply under 600 characters",
