  // 正则 / 主题 → 对话修改, 自定义配色 (regex.js, theme.js, talk.js)
  "正在采用…": "Applying…",
  "AI 回复和用户输入": "AI replies and user input",
  "说说想让回复怎么变，向导写好正则，先拿最新回复试一遍": "Say how replies should change: the guide writes the regex and tries it on the latest reply first",
  "在「对话修改」里说说这一条想怎么改，或者问它为什么不生效": "Say in \"Edit by chat\" how this one should change, or ask why it doesn't work",
  "对话修改正则": "Edit regex by chat",
  "说说想让回复怎么变，或者哪条正则不管用：向导把要改的正则整条写出来，先拿当前对话的最新回复试一遍，给你看匹配到什么、变成什么，勾上的才会存进去。": "Say how replies should change, or which regex isn't working: the guide writes out each script it would change, tries it on this chat's latest reply and shows what it matches and what that becomes; only the ones you tick are saved.",
  "把【】里的内容变成彩色小框": "Put the bracketed lines into small coloured boxes",
  "藏起回复里的思维链": "Hide the chain of thought in replies",
  "这些正则分别在做什么？": "What does each of these regexes do?",
  "「{0}」想怎么改，或者问它为什么不生效": "How should \"{0}\" change? Or ask why it doesn't work",
  "说说想让回复怎么变，比如：把状态栏那段藏起来": "Say how replies should change, e.g. hide the status block",
  "拿最新回复试跑…": "Trying it on the latest reply…",
  "正在读这些正则…": "Reading the regexes…",
  "新正则 · {0}": "New regex · {0}",
  "删除 · {0}": "Delete · {0}",
  "发给模型的不变，不影响缓存": "What's sent to the model stays the same; the cache isn't affected",
  "会改发给模型的内容，下一轮会重新写入一次缓存": "Changes what's sent to the model; the next turn writes the cache once more",
  "作用于：{0}": "Applies to: {0}",
  "效果：{0}": "Effect: {0}",
  "替换为空：删掉匹配到的部分": "Empty replacement: what matches is deleted",
