  "在最新回复里匹配到 {0} 处，前几处变成：": n => `${pl(n, 'match', 'matches')} in the latest reply; the first become:`,
  "（删掉）": "(deleted)",
  "显示出来的样子": "How it shows",
  "已存进正则：{0} 处": n => `${pl(n, 'change', 'changes')} saved to the regexes`,
