  "新故事一开始就同行。最多 {0} 人上场，多的待命。": "Travels with you from the start of a new story. At most {0} fight; the rest stand by.",
  "故事里也这么叫他，用来认出是谁入队、立绘用哪张。": "What the story also calls them: to tell who joined, and which picture is theirs.",
  "战斗里他能用的招，用逗号分开。空着就给强击。": "What they can use in a fight, separated by commas. Left empty: Strike.",
