  "同伴的名字": "Companion's name",
  "加一个同伴": "Add a companion",
  "队伍名册": "Party roster",
  "和你一起打架的人：各有各的属性和技能，在行囊的「队伍」里安排谁上场。故事里写到有人入队时，名册里没有的人按常人加进来。": "Those who fight beside you, each with their own attributes and skills. Choose who fights under Party in the pack. Someone who joins in the story and isn't on the roster joins as an ordinary person.",
  "读卡配置": "Read the card",
  "读卡中…": "Reading…",
  "采用": "Take it",
  "战斗里能用的技能，用逗号分开。效果先按名字猜，下面可以改。空着就给强击和横扫。": "Skills usable in a fight, separated by commas. Their effect is guessed from the name; change it below. Left empty: Power strike and Sweep.",
