  "附文件给向导读：设定、小说原文（txt、md），另一张卡（PNG、JSON），或世界书": "Give the guide a file to read: notes or a novel (txt, md), another card (PNG, JSON), or a worldbook",
  "附资料给向导读：设定、小说原文（txt、md），一张卡（PNG、JSON），或世界书。之后聊天、写方案和写卡都照着它": "Give the guide something to read: notes or a novel (txt, md), a card (PNG, JSON), or a worldbook. The talk, the plan and the writing all go by it",
  "想怎么用这些资料？也可以不写，向导读完会问你": "How should these be used? You can leave this empty: the guide will ask once it has read them",
