  "向导会读到这段对话的摘要、记忆簿、当前变量和原文，之后每次发送都带上，读得越多花的额度越多。": "The assistant reads this chat's summary, memory book, current variables and text. It goes with every request from now on, so reading more uses more of your quota.",
